ALTER TABLE "credential_access_log" DROP CONSTRAINT "credential_access_log_reason_matches";--> statement-breakpoint
ALTER TABLE "credential_access_log" ADD CONSTRAINT "credential_access_log_reason_matches" CHECK (("credential_access_log"."outcome" = 'done' AND "credential_access_log"."reason" IS NULL) OR ("credential_access_log"."outcome" = 'refused' AND "credential_access_log"."reason" IS NOT NULL AND "credential_access_log"."reason" IN ('not_permitted', 'credential_revoked', 'credential_expired', 'value_not_storable', 'key_rejected', 'key_service_refused', 'key_service_unavailable', 'ciphertext_rejected', 'envelope_malformed')));